TOOL = {
  'name': 'find_document',
  'description': 'Поиск документа по номеру или дате. Не использовать для поиска по тексту письма.',
  'input_schema': {
    'type': 'object',
    'properties': {
      'number': {'type': ['string', 'null'], 'description': 'Исходящий номер, например РЦ-ИСХ-6596'},
      'date': {'type': ['string', 'null'], 'description': 'Дата в формате YYYY-MM-DD'},
    },
    'required': ['number', 'date'],
  },
}

def call_tool(name, args):
    try:
        result = TOOLS[name](**args)
    except TimeoutError as err:
        return {'status': 'transient', 'kind': 'timeout',
                'attempted': args, 'retry': True, 'detail': str(err)}
    except PermissionError as err:
        return {'status': 'denied', 'attempted': args,
                'retry': False, 'escalate': True, 'detail': str(err)}
    if not result:
        return {'status': 'empty', 'attempted': args,
                'retry': False, 'note': 'источник ответил, совпадений нет'}
    return {'status': 'ok', 'data': result}

